cat > generate-key.mjs <<'EOF'
// Fetch 1 KiB of Qrypt quantum entropy, derive a 32-byte AES-256 key, and
// verify it with an AES-256-GCM round trip. The key is never printed or written to disk.
import { createCipheriv, createDecipheriv, randomBytes } from "node:crypto";
import { existsSync } from "node:fs";

const API_URL = process.env.QRYPT_API_URL ?? "https://api-eus.qrypt.com/api/v1/quantum-entropy";
const KEY_BYTES = 32;

const ERRORS = {
  400: "size out of range (must be 1-512 KiB)",
  401: "missing, malformed, or expired Authorization header",
  403: "invalid token or monthly quota used",
  429: "rate limited; wait at least 10 seconds before retrying",
  500: "Qrypt service error; retry later",
  503: "Qrypt service busy; retry later",
};

export async function fetchEntropy(token, sizeKiB = 1) {
  const res = await fetch(`${API_URL}?size=${sizeKiB}`, {
    headers: {
      Authorization: `Bearer ${token}`,
      Accept: "application/json",
      "User-Agent": "qrypt-quickstart/1.0",
      "X-Qrypt-Client": "quickstart-js/1.0",
    },
  });
  if (!res.ok) {
    throw new Error(`Qrypt API ${res.status}: ${ERRORS[res.status] ?? res.statusText}`);
  }
  const body = await res.json();
  if (!Array.isArray(body.random) || typeof body.random[0] !== "string") {
    throw new Error("Unexpected Qrypt response: missing random[0]");
  }
  const bytes = Buffer.from(body.random[0], "base64");
  if (bytes.length !== 1024) {
    throw new Error(`Unexpected entropy length: ${bytes.length} bytes (expected 1024)`);
  }
  return bytes;
}

export async function generateAes256Key(token) {
  const entropy = await fetchEntropy(token, 1);
  const key = Buffer.from(entropy.subarray(0, KEY_BYTES));
  entropy.fill(0);
  return key;
}

export function roundTrip(key) {
  const iv = randomBytes(12);
  const plaintext = Buffer.from("hello, quantum world");
  const cipher = createCipheriv("aes-256-gcm", key, iv);
  const ciphertext = Buffer.concat([cipher.update(plaintext), cipher.final()]);
  const tag = cipher.getAuthTag();
  const decipher = createDecipheriv("aes-256-gcm", key, iv);
  decipher.setAuthTag(tag);
  const decrypted = Buffer.concat([decipher.update(ciphertext), decipher.final()]);
  return decrypted.equals(plaintext);
}

async function main() {
  if (existsSync(".env")) process.loadEnvFile(".env");
  const token = process.env.QRYPT_API_KEY;
  if (!token) {
    console.error("QRYPT_API_KEY is not set. Copy .env.example to .env and add your Entropy token.");
    process.exit(1);
  }
  const key = await generateAes256Key(token);
  try {
    if (!roundTrip(key)) throw new Error("AES-256-GCM round trip failed");
    console.log(`OK: generated a ${key.length * 8}-bit AES key from Qrypt quantum entropy; AES-256-GCM round trip passed.`);
  } finally {
    key.fill(0);
  }
}

if (import.meta.url === `file://${process.argv[1]}`) {
  main().catch((err) => {
    console.error(err.message);
    process.exit(1);
  });
}
EOF
cat > test/generate-key.test.mjs <<'EOF'
// Offline tests against a local mock of the Qrypt entropy endpoint.
import { test, before, after } from "node:test";
import assert from "node:assert/strict";
import { createServer } from "node:http";
import { randomBytes } from "node:crypto";

let server;
let lastRequest;
let mockStatus = 200;
const entropy = randomBytes(1024);

before(async () => {
  server = createServer((req, res) => {
    lastRequest = req;
    if (mockStatus !== 200) {
      res.writeHead(mockStatus).end();
      return;
    }
    res.writeHead(200, { "Content-Type": "application/json" });
    res.end(JSON.stringify({ random: [entropy.toString("base64")], size: 1 }));
  });
  await new Promise((r) => server.listen(0, "127.0.0.1", r));
  process.env.QRYPT_API_URL = `http://127.0.0.1:${server.address().port}/api/v1/quantum-entropy`;
});

after(() => server.close());

test("key is the first 32 decoded entropy bytes and round-trips", async () => {
  mockStatus = 200;
  const { generateAes256Key, roundTrip } = await import("../generate-key.mjs");
  const key = await generateAes256Key("test-token");
  assert.equal(key.length, 32);
  assert.ok(key.equals(entropy.subarray(0, 32)));
  assert.ok(roundTrip(key));
  assert.equal(lastRequest.url, "/api/v1/quantum-entropy?size=1");
  assert.equal(lastRequest.headers.authorization, "Bearer test-token");
  assert.equal(lastRequest.headers["user-agent"], "qrypt-quickstart/1.0");
});

test("403 maps to a clear error without leaking the token", async () => {
  mockStatus = 403;
  const { generateAes256Key } = await import("../generate-key.mjs");
  await assert.rejects(generateAes256Key("secret-token"), (err) => {
    assert.match(err.message, /403: invalid token or monthly quota used/);
    assert.ok(!err.message.includes("secret-token"));
    return true;
  });
});
EOF
npm test > /tmp/qrypt-test.log 2>&1; echo "exit=$?"; cat /tmp/qrypt-test.log; QRYPT_API_KEY= node generate-key.mjs < /dev/null; echo "exit=$?"

